import re
import os

def task_func(request):
    def build_response(status_line, body=""):
        if body:
            return f"HTTP/1.1 {status_line}\r\n\r\n{body}"
        return f"HTTP/1.1 {status_line}\r\n\r\n"

    if not isinstance(request, str) or not request.strip():
        return build_response("400 Bad Request", "Bad Request")

    request_line = request.splitlines()[0].strip()
    match = re.match(r"^GET\s+(\S+)\s+HTTP/(1\.[01])$", request_line)
    if not match:
        return build_response("400 Bad Request", "Bad Request")

    raw_path = match.group(1)

    # Ignore query string and fragment, normalize separators
    path = raw_path.split("?", 1)[0].split("#", 1)[0].replace("\\", "/")

    # Map root request to a default file if present; otherwise treat as missing
    if path == "/":
        path = "index.html"
    else:
        path = path.lstrip("/")

    if not path or ":" in path:
        return build_response("400 Bad Request", "Bad Request")

    base_dir = os.getcwd()
    target_path = os.path.abspath(os.path.join(base_dir, path))

    try:
        if os.path.commonpath([base_dir, target_path]) != os.path.abspath(base_dir):
            return build_response("400 Bad Request", "Bad Request")
    except ValueError:
        return build_response("400 Bad Request", "Bad Request")

    if not os.path.isfile(target_path):
        return build_response("404 Not Found", "Not Found")

    try:
        with open(target_path, "rb") as f:
            content_bytes = f.read()
    except PermissionError:
        return build_response("403 Forbidden", "Forbidden")
    except OSError:
        return build_response("500 Internal Server Error", "Internal Server Error")

    try:
        content = content_bytes.decode("utf-8")
    except UnicodeDecodeError:
        content = content_bytes.decode("latin-1")

    return f"HTTP/1.1 200 OK\r\nContent-Length: {len(content_bytes)}\r\n\r\n{content}"
